1|// Pre-commit secret scan: staged text files must hold no credentials.
2|// With --all it scans every tracked file at HEAD plus full git history.
3|// Plain Node, no dependencies. Findings never print the secret itself.
4|import { execFileSync } from 'node:child_process';
5|import { fileURLToPath } from 'node:url';
6|
7|export const ALLOW_MARKER = 'secret-scan:allow';
8|// Paths the secret scan skips: lockfiles only, which we do not author.
9|// Binary blobs are skipped separately via isBinaryBuffer. Everything else
10|// is scanned, including agent-logs/, public/ and .agents/skills/.
11|export const SECRET_IGNORE_PATTERNS = [
12|  'package-lock.json',
13|  'pnpm-lock.yaml',
14|  'yarn.lock',
15|  'bun.lockb',
16|  'uv.lock',
17|  'poetry.lock',
18|  '*.lock',
19|];
20|
21|export function isSecretSkipped(path) {
22|  const slash = path.lastIndexOf('/');
23|  const name = slash === -1 ? path : path.slice(slash + 1);
24|  for (const pattern of SECRET_IGNORE_PATTERNS) {
25|    if (pattern.includes('*')) {
26|      if (name.endsWith(pattern.slice(1))) return true;
27|    } else if (name === pattern) {
28|      return true;
29|    }
30|  }
31|  return false;
32|}
33|export const ENTROPY_THRESHOLD = 3.5;
34|export const ENTROPY_MIN_LENGTH = 20;
35|
36|// Each rule needs a token-looking suffix so prose that names a prefix
37|// (like this file) does not match. Keep it that way when adding rules.
38|export const RULES = [
39|  { name: 'jev', pattern: /\bjv_live_[A-Za-z0-9_-]{16,}/ },
40|  { name: 'openai', pattern: /sk-[A-Za-z0-9_-]{20,}/ },
41|  { name: 'meta-llm', pattern: /LLM\|[A-Za-z0-9_-]{10,}/ },
42|  { name: 'meta-bearer', pattern: /Bearer\s+[A-Za-z0-9._~-]{20,}/ },
43|  { name: 'github', pattern: /(?:ghp|gho)_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}/ },
44|  { name: 'aws', pattern: /AKIA[0-9A-Z]{16}/ },
45|  { name: 'private-key', pattern: /-----BEGIN (?:[A-Z0-9]+ )*PRIVATE KEY-----/ },
46|  { name: 'redis-url', pattern: /rediss?:\/\/[^:\s]+:[^@\s]+@/ },
47|];
48|
49|const ASSIGNMENT = /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*?)\s*$/;
50|const SECRET_NAME = /(KEY|TOKEN|SECRET|PASSWORD)$/i;
51|const PLACEHOLDERS = ['your-', 'your_', 'changeme', 'change-me', 'xxx', '<', '>'];
52|
53|// File names refused whatever they hold. .env.example stays allowed.
54|export function isForbiddenFilename(path) {
55|  const slash = path.lastIndexOf('/');
56|  const name = slash === -1 ? path : path.slice(slash + 1);
57|  return (
58|    name === '.env' ||
59|    name === '.env.local' ||
60|    (name.startsWith('.env.') && name.endsWith('.local')) ||
61|    name.endsWith('.pem')
62|  );
63|}
64|
65|export function shannonEntropy(text) {
66|  const counts = new Map();
67|  for (const char of text) counts.set(char, (counts.get(char) ?? 0) + 1);
68|  let entropy = 0;
69|  for (const count of counts.values()) {
70|    const p = count / text.length;
71|    entropy -= p * Math.log2(p);
72|  }
73|  return entropy;
74|}
75|
76|function unquote(value) {
77|  if (value.length >= 2) {
78|    const first = value[0];
79|    const last = value[value.length - 1];
80|    if ((first === '"' || first === "'") && first === last) return value.slice(1, -1);
81|  }
82|  return value;
83|}
84|
85|function isPlaceholderValue(value) {
86|  const lower = value.toLowerCase();
87|  return PLACEHOLDERS.some((marker) => lower.includes(marker));
88|}
89|
90|export function redact(secret) {
91|  return secret.slice(0, 4) + '…';
92|}
93|
94|// Pure and testable: findings look like { path, line, rule, preview }.
95|export function scanContent(path, content) {
96|  const findings = [];
97|  const exampleFile = path === '.env.example' || path.endsWith('/.env.example');
98|  const lines = content.split('\n');
99|  for (let index = 0; index < lines.length; index++) {
100|    const line = lines[index];
101|    if (line.includes(ALLOW_MARKER)) continue;
102|    const assignment = ASSIGNMENT.exec(line);
103|    if (exampleFile && assignment) {
104|      const value = unquote(assignment[2]);
105|      if (value === '' || isPlaceholderValue(value)) continue;
106|    }
107|    for (const rule of RULES) {
108|      const match = rule.pattern.exec(line);
109|      if (match) {
110|        findings.push({ path, line: index + 1, rule: rule.name, preview: redact(match[0]) });
111|      }
112|    }
113|    if (assignment && SECRET_NAME.test(assignment[1])) {
114|      const value = unquote(assignment[2]);
115|      if (value.length >= ENTROPY_MIN_LENGTH && shannonEntropy(value) > ENTROPY_THRESHOLD) {
116|        findings.push({ path, line: index + 1, rule: 'high-entropy', preview: redact(value) });
117|      }
118|    }
119|  }
120|  return findings;
121|}
122|
123|export function isBinaryBuffer(buffer) {
124|  const head = buffer.subarray(0, 8000);
125|  return head.includes(0);
126|}
127|
128|function splitNul(output) {
129|  const text = output.toString('utf8');
130|  return text.length === 0 ? [] : text.split('\0').filter((entry) => entry !== '');
131|}
132|
133|function stagedPaths() {
134|  const output = execFileSync(
135|    'git',
136|    ['diff', '--cached', '--name-only', '--diff-filter=ACMR', '-z'],
137|    { encoding: 'buffer', stdio: ['ignore', 'pipe', 'ignore'] },
138|  );
139|  return splitNul(output);
140|}
141|
142|function headPaths() {
143|  const output = execFileSync('git', ['ls-tree', '-r', '--name-only', 'HEAD', '-z'], {
144|    encoding: 'buffer',
145|    stdio: ['ignore', 'pipe', 'ignore'],
146|  });
147|  return splitNul(output);
148|}
149|
150|function showBlob(revision, path) {
151|  return execFileSync('git', ['show', `${revision}:${path}`], {
152|    encoding: 'buffer',
153|    maxBuffer: 8 * 1024 * 1024,
154|    stdio: ['ignore', 'pipe', 'ignore'],
155|  });
156|}
157|
158|function scanBlob(revision, path, findings) {
159|  if (isForbiddenFilename(path)) {
160|    findings.push({ path, line: 0, rule: 'forbidden-filename', preview: '(blocked file name)' });
161|    return;
162|  }
163|  if (isSecretSkipped(path)) return;
164|  let blob;
165|  try {
166|    blob = showBlob(revision, path);
167|  } catch {
168|    console.error(`warning: cannot read staged content of ${path}, skipping it`);
169|    return;
170|  }
171|  if (isBinaryBuffer(blob)) return;
172|  findings.push(...scanContent(path, blob.toString('utf8')));
173|}
174|
175|function scanHistory(findings) {
176|  let output;
177|  try {
178|    output = execFileSync('git', ['log', '-p', '--all'], {
179|      encoding: 'buffer',
180|      maxBuffer: 64 * 1024 * 1024,
181|      stdio: ['ignore', 'pipe', 'ignore'],
182|    });
183|  } catch {
184|    return; // No history yet.
185|  }
186|  let file = '<history>';
187|  let removed = null;
188|  for (const line of output.toString('utf8').split('\n')) {
189|    if (line.startsWith('--- a/')) {
190|      removed = line.slice('--- a/'.length);
191|    } else if (line.startsWith('+++ b/')) {
192|      file = line.slice('+++ b/'.length);
193|    } else if (line === '+++ /dev/null') {
194|      file = removed ?? '<deleted>'; // Deleted file: label with its old path.
195|    } else if (line.startsWith('+') && !line.startsWith('+++')) {
196|      if (!isSecretSkipped(file)) findings.push(...scanContent(`${file} (history)`, line.slice(1)));
197|    }
198|  }
199|}
200|
201|function report(findings) {
202|  if (findings.length === 0) return 0;
203|  console.error(`error: secret scan found ${findings.length} problem(s):`);
204|  for (const finding of findings) {
205|    const location = finding.line > 0 ? `${finding.path}:${finding.line}` : finding.path;
206|    console.error(`  ${location} [${finding.rule}] ${finding.preview}`);
207|  }
208|  console.error('Remove the secret (and any history that holds it), use an env var, then commit again.');
209|  return 1;
210|}
211|
212|function main() {
213|  const findings = [];
214|  if (process.argv.includes('--all')) {
215|    let paths;
216|    try {
217|      paths = headPaths();
218|    } catch {
219|      console.error('note: no commits yet, nothing to scan with --all');
220|      return 0;
221|    }
222|    for (const path of paths) scanBlob('HEAD', path, findings);
223|    scanHistory(findings);
224|    return report(findings);
225|  }
226|  let paths;
227|  try {
228|    paths = stagedPaths();
229|  } catch {
230|    console.error('warning: not a git repo, skipping the secret scan');
231|    return 0;
232|  }
233|  for (const path of paths) scanBlob('', path, findings);
234|  return report(findings);
235|}
236|
237|const invokedAsScript = process.argv[1] === fileURLToPath(import.meta.url);
238|if (invokedAsScript) process.exit(main());

